def evaluate(self, evaluation_metrics: Optional[List[str]] = None) -> Dict[str, Any]:
    ...
    N = self.N
    if "adoption_rate_over_time" in metrics:
        results["adoption_rate_over_time"] = adop
    if "average_adoption_rate" in metrics:
        results["average_adoption_rate"] = sum(adop) / len(adop)
    if "time_to_reach_threshold" in metrics:
        thr = float(self.cfg.get("adoption_threshold", self.cfg.get("target_adoption_threshold", 0.7)))
        results["time_to_reach_threshold"] = time_to_threshold(adop, thr, window=1)
    if "sustained_adoption_days" in metrics:
        thr = float(self.cfg.get("adoption_threshold", self.cfg.get("target_adoption_threshold", 0.7)))
        best = cur = 0
        for v in adop:
            cur = cur + 1 if v >= thr else 0
            best = max(best, cur)
        results["sustained_adoption_days"] = best
    if "policy_compliance_rate" in metrics:
        denom = max(1, self._visits_under_mandate)
        results["policy_compliance_rate"] = 1.0 - (self._violations_under_mandate / denom)
    if "adoption_variance" in metrics:
        decs = self._precomputed_deciles or self._income_deciles()
        vals = []
        for dec in decs:
            if dec:
                vals.append(sum(1.0 if self.people[i].current_mask_use else 0.0 for i in dec) / len(dec))
        mean_v = sum(vals)/len(vals) if vals else 0.0
        results["adoption_variance"] = sum((v-mean_v)**2 for v in vals)/len(vals) if vals else 0.0
    if "misinformation_impact" in metrics:
        window = int(self.cfg.get("misinformation_impact_window_days", 5))
        impacts = []
        for d in getattr(self, "_misinfo_events", []):
            if d+1 < len(adop):
                pre = adop[d]
                post = adop[min(d+window, len(adop)-1)]
                impacts.append(pre - post)
        results["misinformation_impact"] = (sum(impacts)/len(impacts)) if impacts else 0.0
    if "cumulative_person_days_masked" in metrics:
        results["cumulative_person_days_masked"] = sum(a * N for a in adop)

